<?php
require_once __DIR__.'/../config/conexao.php'; require_once __DIR__.'/../includes/funcoes.php'; exigirLogin();
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: ../html/pagamento.php');exit;}
$itens=json_decode($_POST['itens']??'[]',true); // O carrinho é enviado pelo formulário JS na submissão.
if(!is_array($itens)||!$itens){$_SESSION['flash']='Carrinho vazio ou inválido.';header('Location: ../html/carrinho.php');exit;}
$quantidades=[];foreach($itens as $item){if(!is_array($item)){$_SESSION['flash']='Carrinho inválido.';header('Location: ../html/carrinho.php');exit;}$id=(int)($item['id']??0);$q=max(1,min(50,(int)($item['quantidade']??1)));if($id<1){$_SESSION['flash']='Produto inválido no carrinho.';header('Location: ../html/carrinho.php');exit;}$quantidades[$id]=($quantidades[$id]??0)+$q;}
$metodo=$_POST['metodo']??'pix';if(!in_array($metodo,['pix','cartao','dinheiro'],true))$metodo='pix';
try{$pdo->beginTransaction();$ids=array_keys($quantidades);$marks=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT id,nome,preco,estoque FROM produtos WHERE ativo=1 AND id IN ($marks) FOR UPDATE");$st->execute($ids);$produtos=[];foreach($st as $p)$produtos[$p['id']]=$p;$total=0;$linhas=[];foreach($quantidades as $id=>$q){if(!isset($produtos[$id])||$produtos[$id]['estoque']<$q)throw new RuntimeException('Um produto não está disponível na quantidade solicitada.');$p=$produtos[$id];$total+=(float)$p['preco']*$q;$linhas[]=[$id,$p['nome'],$q,(float)$p['preco']];}$st=$pdo->prepare('INSERT INTO pedidos(usuario_id,total,metodo_pagamento) VALUES(?,?,?)');$st->execute([$_SESSION['usuario_id'],$total,$metodo]);$pedido=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO itens_pedido(pedido_id,produto_id,nome_produto,quantidade,preco_unitario) VALUES(?,?,?,?,?)');$upd=$pdo->prepare('UPDATE produtos SET estoque=estoque-? WHERE id=?');foreach($linhas as $l){$ins->execute([$pedido,$l[0],$l[1],$l[2],$l[3]]);$upd->execute([$l[2],$l[0]]);}$pdo->commit();$_SESSION['limpar_carrinho']=true;$_SESSION['flash']='Pedido #'.$pedido.' confirmado! Pagamento demonstrativo: '.$metodo.'.';header('Location: ../html/painel.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['flash']=$e instanceof RuntimeException?$e->getMessage():'Não foi possível registrar o pedido.';header('Location: ../html/carrinho.php');exit;}
